WITH scored AS (SELECT id, email, country, signup_date, AVG(age) OVER w_running AS running_avg_age, SUM(age) OVER w_running AS running_sum_age, COUNT(age) OVER w_running AS running_count_age FROM customers WINDOW w_running AS (PARTITION BY city ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, email, running_avg_age, running_sum_age FROM scored ORDER BY running_avg_age DESC
